import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { useFormik } from "formik";
import { useDispatch, useSelector } from "react-redux";
import { useStateContext } from "../../contexts/ContextProvider";
import { Link, Navigate, useNavigate } from "react-router-dom";
import { toast, ToastContainer } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import CustomForm from "../../components/forms/CustomForm";
import CustomFormItem from "../../components/forms/CustomFormItem";
import CustomInput from "../../components/forms/CustomInput";
import CustomSelectReactSelect from "../../components/forms/CustomSelectReactSelect";
import CustomDatePicker from "../../components/forms/CustomDatePicker";
import CustomCheckBox from "../../components/forms/CustomCheckBox";
import FileUploader from "../../components/FileUploader";
import useApi from "../../hooks/useApi";
import "react-datepicker/dist/react-datepicker.css";
import Loading from "../../components/Loading";
import countriesApi from "../../api/countriesApi";
import countiesApi from "../../api/countiesApi";
import { Button } from "@heroui/react";
import registerApi from "../../api/registerApi";

const CorporateUserFormModal = () => {
  const navigate = useNavigate();
  const moment = require("moment");
  const dispatch = useDispatch();
  const { currentColor } = useStateContext();
  const user = useSelector((state) => state.Auth.user);
  // const errors = useSelector((state) => state.Auth.errors);

  const [errors, seterrors] = useState([]);
  const loading = useSelector((state) => state.Auth.loading);
  const created = useSelector((state) => state.Auth.created);
  const formik = useFormik({
    initialValues: {
      documents: [],
      accepted_terms: "",
      first_name: "",
      last_name: "",
      phone: "",
      email: "",
      identifier_type: "",
      identifier_number: "",
      password: "",
      confirm_password: "",
      date_of_birth: "",
      gender: "",
      country: "",
      county: "",
    },

    validationSchema: Yup.object({
      documents: Yup.array().label("Images"),
      accepted_terms: Yup.string().required().label("Accept terms"),
      county: Yup.object().required().label("County"),
      country: Yup.object().required().label("Country"),
      date_of_birth: Yup.string().required().label("Date of birth"),
      first_name: Yup.string().required().label("First name"),
      last_name: Yup.string().required().label("Last name"),
      identifier_type: Yup.object().required().label("Identifier Type"),
      identifier_number: Yup.string().required().label("Identifier Number"),
      phone: Yup.string().required().label("Phone"),
      email: Yup.string().email().required().label("Email"),
      gender: Yup.object().required().label("Gender"),
      password: Yup.string()
        .min(6, "Must be 6 characters or more")
        .required("Enter password")
        .label("Password"),
      confirm_password: Yup.string()
        .oneOf([Yup.ref("password"), null], "Passwords must match")
        .required("Confirm your password"),
    }),

    onSubmit: (values) => {
      let data = new FormData();

      console.log("VALZ", values);

      data.append("accepted_terms", values.accepted_terms);
      data.append("first_name", values.first_name);
      data.append("last_name", values.last_name);
      data.append("identifier_type", values.identifier_type.value);
      data.append("identifier_number", values.identifier_number);
      data.append("email", values.email);
      data.append("phone", values.phone);
      data.append("gender", values.gender.value);
      data.append(
        "date_of_birth",
        moment(values.date_of_birth).format("YYYY-MM-DD")
      );
      data.append("county", values.county.value);
      data.append("country", values.country.value);
      // data.append("region", values.region.value);
      data.append("password", values.password);

      values.documents.map((x) => {
        data.append("documents", x);
      });
      registerUser(data);
      // dispatch(registerUser(data));
    },
  });

  useEffect(() => {
    if (created && user) {
      navigate("/login");
    }
  }, [created, user]);

  // useEffect(() => {
  //   if (errors && errors.length) {
  //     errors.map((x) => {
  //       toast.error(x);
  //     });
  //   }
  // }, [errors]);

  //Register

  const doRegisterApi = useApi(registerApi.registerAction);

  const registerUser = async (data) => {
    const res = await doRegisterApi.request(data);
    console.log("Result", res);
    seterrors(res.data.errors.errors);
  };
  useEffect(() => {
    if (doRegisterApi.data && doRegisterApi.data.response_code === 1) {
      toast.error(doRegisterApi.response_message);
    }

    // console.log("doRegisterApi.data", doRegisterApi.data);
  }, [doRegisterApi.data]);

  //Countries
  const [countries, setCountries] = useState([]);
  const getCountriesApi = useApi(countriesApi.countriesAction);
  useEffect(() => {
    if (getCountriesApi.data && getCountriesApi.data.length) {
      setCountries(
        getCountriesApi.data.map((i) => ({ label: i.title, value: i.id }))
      );
    }
    console.log("Countries", getCountriesApi.data);
  }, [getCountriesApi.data]);

  const getCountries = async () => {
    await getCountriesApi.request({
      action: "GetCountries",
    });
  };

  //Counties
  const [counties, setCounties] = useState([]);
  const getCountiesApi = useApi(countiesApi.countiesAction);
  const getCounties = async () => {
    await getCountiesApi.request({
      action: "GetCounties",
    });
  };

  useEffect(() => {
    if (getCountiesApi.data && getCountiesApi.data.length) {
      setCounties(
        getCountiesApi.data.map((i) => ({ label: i.title, value: i.id }))
      );
    }
    console.log("Countries", getCountiesApi.data);
  }, [getCountiesApi.data]);

  useEffect(() => {
    getCountries();
    getCounties();
  }, []);

  //Handle select changes

  const handleGenderChange = (e) => {
    formik.setFieldValue("gender", e);
  };

  const handleSelectCountry = (e) => {
    formik.setFieldValue("country", e);
  };

  const handleIdentifierTypeChange = (e) => {
    formik.setFieldValue("identifier_type", e);
  };
  const handleSelectCounty = (e) => {
    formik.setFieldValue("county", e);
  };

  const handleDateOfBirthChange = (date, dateString) => {
    formik.setFieldValue("date_of_birth", dateString);
  };

  //Remove file uploader selected image

  const handleRemoveSelectedImage = (file) => {
    console.log("file", file);
    // formik.values.documents.filter((x) => x.preview !== file.preview);

    formik.setFieldValue(
      "documents",
      formik.values.documents.filter((x) => x.preview !== file.preview)
    );
  };

  return doRegisterApi.loading ? (
    <Loading loading={doRegisterApi.loading} />
  ) : (
    <div className="container m-auto bg-gray-100 ">
      <div className="m-1">
        <ToastContainer position="bottom-center" theme="colored" />
      </div>
      <div className="text-center py-1">
        <img
          style={{ color: currentColor }}
          className="mx-auto h-5 w-auto"
          src="https://tailwindui.com/img/logos/workflow-mark-indigo-600.svg"
          alt="Workflow"
        />
        <h2 className="mt-2 text-center text-3xl font-extrabold text-gray-900">
          Register now
        </h2>
        <div className="flex justify-center my-1">
          <p className="mr-2">Already registered?</p>
          <Link
            style={{ color: currentColor }}
            className="text-blue-500"
            to="/login"
          >
            Sign In
          </Link>
        </div>
      </div>
      <div className=" flex justify-center items-center bg-gray-100">
        {loading ? (
          <Loading loading={loading} />
        ) : (
          <CustomForm
            layout="vertical"
            handleFinish={formik.handleSubmit}
            className="grid flex justify-center items-center"
          >
            <div className="w-full grid grid-cols-2 mt- gap-1">
              {countries && countries.length && (
                <CustomFormItem
                  touched={formik.touched.country}
                  error={formik.errors.country}
                >
                  <CustomSelectReactSelect
                    className="text-start"
                    name="country"
                    id="country"
                    label="Country"
                    size="large"
                    onChange={(e) => handleSelectCountry(e)}
                    value={formik.values.country}
                    placeholder="Select country"
                    options={countries}
                  />
                </CustomFormItem>
              )}
              {counties && counties.length && (
                <CustomFormItem
                  touched={formik.touched.county}
                  error={formik.errors.county}
                >
                  <CustomSelectReactSelect
                    className="text-start"
                    name="county"
                    id="county"
                    label="Region"
                    size="large"
                    onChange={(e) => handleSelectCounty(e)}
                    value={formik.values.county}
                    placeholder="Select region"
                    options={counties}
                  />
                </CustomFormItem>
              )}
              <CustomFormItem
                touched={formik.touched.first_name}
                error={formik.errors.first_name}
              >
                <CustomInput
                  id="first_name"
                  name="first_name"
                  onChange={formik.handleChange}
                  placeholder="Enter first name"
                  size="large"
                  type="text"
                  value={formik.values.first_name}
                />
              </CustomFormItem>
              <CustomFormItem
                touched={formik.touched.last_name}
                error={formik.errors.last_name}
              >
                <CustomInput
                  id="last_name"
                  name="last_name"
                  onChange={formik.handleChange}
                  placeholder="Enter last name"
                  size="large"
                  type="text"
                  value={formik.values.last_name}
                />
              </CustomFormItem>
              <CustomFormItem
                touched={formik.touched.phone}
                error={formik.errors.phone}
              >
                <CustomInput
                  id="phone"
                  name="phone"
                  onChange={formik.handleChange}
                  placeholder="Enter  phone"
                  size="large"
                  type="text"
                  value={formik.values.phone}
                />
              </CustomFormItem>

              <CustomFormItem
                touched={formik.touched.email}
                error={formik.errors.email}
              >
                <CustomInput
                  id="email"
                  name="email"
                  onChange={formik.handleChange}
                  placeholder="Enter email"
                  size="large"
                  type="email"
                  value={formik.values.email}
                />
              </CustomFormItem>
              <CustomFormItem
                touched={formik.touched.identifier_type}
                error={formik.errors.identifier_type}
              >
                <CustomSelectReactSelect
                  name="identifier_type"
                  id="identifier_type"
                  label="National Identifier Type"
                  size="large"
                  onChange={(e) => handleIdentifierTypeChange(e)}
                  value={formik.values.identifier_type}
                  placeholder="Select identifier type"
                  options={[
                    { value: "NationalId", label: "National ID" },
                    { value: "Passport", label: "Passport" },
                  ]}
                />
              </CustomFormItem>
              <CustomFormItem
                touched={formik.touched.identifier_number}
                error={formik.errors.identifier_number}
              >
                <CustomInput
                  id="identifier_number"
                  name="identifier_number"
                  onChange={formik.handleChange}
                  placeholder="Enter identifier number"
                  size="large"
                  type="text"
                  value={formik.values.identifier_number}
                />
              </CustomFormItem>
              <CustomFormItem
                touched={formik.touched.gender}
                error={formik.errors.gender}
              >
                <CustomSelectReactSelect
                  name="gender"
                  id="gender"
                  label="Gender"
                  size="large"
                  onChange={(e) => handleGenderChange(e)}
                  value={formik.values.gender}
                  placeholder="Select gender"
                  options={[
                    { value: "Female", label: "Female" },
                    { value: "Male", label: "Male" },
                  ]}
                />
              </CustomFormItem>

              <CustomFormItem
                touched={formik.touched.date}
                error={formik.errors.date}
              >
                <CustomDatePicker
                  id="date_of_birth"
                  name="date_of_birth"
                  size="large"
                  placeholder="Select date of birth"
                  onChange={handleDateOfBirthChange}
                />
              </CustomFormItem>

              <CustomFormItem
                touched={formik.touched.password}
                error={formik.errors.password}
              >
                <CustomInput
                  id="password"
                  name="password"
                  onChange={formik.handleChange}
                  placeholder="Enter password"
                  size="large"
                  type="password"
                  value={formik.values.password}
                />
              </CustomFormItem>
              <CustomFormItem
                touched={formik.touched.confirm_password}
                error={formik.errors.confirm_password}
              >
                <CustomInput
                  id="confirm_password"
                  name="confirm_password"
                  onChange={formik.handleChange}
                  placeholder="Enter confirm_password"
                  size="large"
                  type="password"
                  value={formik.values.confirm_password}
                />
              </CustomFormItem>
              <CustomFormItem
                touched={formik.touched.accepted_terms}
                error={formik.errors.accepted_terms}
              >
                <CustomCheckBox
                  id="accepted_terms"
                  label="Accept terms and conditions"
                  name="accepted_terms"
                  value={formik.values.accepted_terms}
                  onChange={(e) =>
                    formik.setFieldValue("accepted_terms", e.target.checked)
                  }
                />
              </CustomFormItem>
            </div>
            <div className="grid grid-cols-1 max-w-md">
              <CustomFormItem>
                <div className="bg-white max-w-md">
                  <FileUploader
                    placeholder="Upload front and back page of National ID or page 1 and 4 of passport"
                    formik={formik}
                    name="documents"
                    types=".png,.jpg,.jpeg"
                    value={formik.values.documents}
                    accept={{
                      "image/png": [".png"],
                      "image/jpeg": [".jpeg"],
                    }}
                  />
                  {formik.values.documents &&
                    formik.values.documents.length > 0 && (
                      <div className="shadow-md rounded my-5 bg-zinc-100 p-5">
                        <h2 className="text-center font-bold mb-5">
                          Images selected for upload
                        </h2>
                        <div className="container flex flex-wrap mx-auto">
                            <div className="grid grid-cols-4 h-48 w-48 sm:grid-cols-4 gap-3">
                            {formik.values.documents?.map((file) => (
                              <div
                                className="md:shrink-0 rounded "
                                key={file.preview}
                              >
                                <button
                                  onClick={() =>
                                    handleRemoveSelectedImage(file)
                                  }
                                  className="flex  absolute text-red-800 border-red-800 border"
                                >
                                  x
                                </button>
                                <img
                                  className=" object-cover w-48 h-48 shadow-md"
                                  src={file.preview}
                                  alt=""
                                />
                              </div>
                            ))}
                          </div>
                        </div>
                      </div>
                    )}
                </div>
              </CustomFormItem>
            </div>
            <div className="w-full flex items-center mt-2 justify-center ">
              <Button className="w-36 rounded-md" color="primary" type="submit">
                Submit
              </Button>
            </div>
          </CustomForm>
        )}
      </div>
    </div>
  );
};

export default CorporateUserFormModal;
